 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and not seen[yy][xx] and grid[yy][xx] != 0:
                        seen[yy][xx] = True
                        q.append((yy, xx))
            comps.append(comp)
    # The component with the fewest 9 markers is the one to erase.
    target = min(comps, key=lambda comp: sum(grid[r][c] == 9 for r, c in comp))
    out = [row[:] for row in grid]
    for r, c in target:
        out[r][c] = 0
    return out
